+class ContactForm {
+  constructor() {
+    this.form = document.getElementById('contactForm');
+    this.fields = {
+      fullName: document.getElementById('fullName'),
+      email: document.getElementById('email'),
+      phone: document.getElementById('phone'),
+    };
+    this.errorElements = {
+      fullName: document.getElementById('fullName-error'),
+      email: document.getElementById('email-error'),
+      phone: document.getElementById('phone-error'),
+    };
+
+    this.init();
+  }
+
+  init() {
+    this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+
+    Object.keys(this.fields).forEach((fieldName) => {
+      const field = this.fields[fieldName];
+      field.addEventListener('blur', () => this.validateField(fieldName));
+      field.addEventListener('input', () => this.clearError(fieldName));
+    });
+  }
+
+  validateField(fieldName) {
+    const field = this.fields[fieldName];
+    const errorEl = this.errorElements[fieldName];
+
+    let error = '';
+
+    if (fieldName === 'fullName') {
+      if (!field.value.trim()) {
+        error = 'Error: Please enter your full name.';
+      } else if (field.value.trim().length < 2) {
+        error = 'Error: Full name must be at least 2 characters.';
+      }
+    } else if (fieldName === 'email') {
+      if (!field.value.trim()) {
+        error = 'Error: Please enter your email address.';
+      } else if (!this.isValidEmail(field.value)) {
+        error = 'Error: Please enter a valid email (e.g., name@example.com).';
+      }
+    } else if (fieldName === 'phone') {
+      if (field.value.trim() && !this.isValidPhone(field.value)) {
+        error = 'Error: Please enter a valid phone number.';
+      }
+    }
+
+    if (error) {
+      field.setAttribute('aria-invalid', 'true');
+      errorEl.textContent = error;
+    } else {
+      field.setAttribute('aria-invalid', 'false');
+      errorEl.textContent = '';
+    }
+
+    return !error;
+  }
+
+  clearError(fieldName) {
+    const field = this.fields[fieldName];
+    const errorEl = this.errorElements[fieldName];
+
+    errorEl.textContent = '';
+    field.setAttribute('aria-invalid', 'false');
+  }
+
+  isValidEmail(email) {
+    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+    return emailRegex.test(email);
+  }
+
+  isValidPhone(phone) {
+    const phoneRegex = /^[\d\s\-().+]+$/.test(phone) && phone.replace(/\D/g, '').length >= 10;
+    return phoneRegex;
+  }
+
+  handleSubmit(e) {
+    e.preventDefault();
+
+    const isFullNameValid = this.validateField('fullName');
+    const isEmailValid = this.validateField('email');
+    const isPhoneValid = this.validateField('phone');
+
+    if (!isFullNameValid) {
+      this.fields.fullName.focus();
+      return;
+    }
+
+    if (!isEmailValid) {
+      this.fields.email.focus();
+      return;
+    }
+
+    if (!isPhoneValid) {
+      this.fields.phone.focus();
+      return;
+    }
+
+    this.submitForm();
+  }
+
+  submitForm() {
+    const formData = {
+      fullName: this.fields.fullName.value,
+      email: this.fields.email.value,
+      phone: this.fields.phone.value,
+    };
+
+    console.log('Form submitted with data:', formData);
+
+    this.form.reset();
+
+    Object.keys(this.fields).forEach((fieldName) => {
+      this.fields[fieldName].setAttribute('aria-invalid', 'false');
+      this.errorElements[fieldName].textContent = '';
+    });
+  }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+  new ContactForm();
+});
+
")

